DELETE = {'pb755bd5': 'второй экземпляр издания pba2bfae', 'sb32aa95': 'отдельный файл обложки издания sbc8c53f', 'sb984188': 'отдельный файл титульного листа издания sba9aeff'}
for code, dd in DISC.items():
    S = dd['dir'] + '/2. Источники/'; MP = D5 + 'manifest_%s.json' % code; man = json.load(open(MP, encoding='utf-8')); out = []; n = 0
    for m in man:
        k = m['key']
        if k in DELETE:
            if os.path.exists(S + m['dst']): os.remove(S + m['dst'])
            print('удалён:', k, DELETE[k]); continue
        if k in FIX and m.get('how') == 'каталог':
            au, title, kind, pub, year, sci = FIX[k]; year = year or m['year']
            kindc = kind[:1].upper() + kind[1:] if kind and kind.lower() not in title.lower() else ''
            tail = '. '.join(x for x in [kindc, '%s, %d' % (pub, year)] if x)
            name = fit(lambda t: '. '.join(x for x in [au.rstrip('.') if au.endswith('и др.') else au, t, tail] if x) + '.pdf', title, cap=150).replace('…..', '….').replace('и др. ', 'и др. ')
            if au.endswith('и др.'): name = name.replace(au.rstrip('.') + '. ', au + ' ', 1)
            folder = (D4OLD if year < 2023 else D4) if sci else D3
            assert len(name.encode('utf-8')) <= 225 and not os.path.exists(S + folder + name), name
            os.makedirs(S + folder, exist_ok=True); os.rename(S + m['dst'], S + folder + name)
            m.update(authors=au, title=title, kind=kind, pub=pub, year=year, cat='sci' if sci else 'book', old=bool(sci and year < 2023), dst=folder + name, how='титульный лист (описание составлено вручную)'); n += 1
        out.append(m)
    json.dump(out, open(MP, 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
    print(code, 'описано вручную:', n, 'осталось по каталогу:', sum(1 for m in out if m.get('how') == 'каталог'))
